import type { UIMessage } from "ai";
import { index, integer, jsonb, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

// Conversations and their messages. Messages store the AI SDK UIMessage parts as JSON,
// so every step (text, reasoning, tool calls and their results) is kept as it streamed.

export const conversations = pgTable("conversations", {
  // Generated by the browser; it is also the AI SDK chat id sent with each request.
  id: uuid("id").primaryKey(),
  title: text("title").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export type MessageStatus = "streaming" | "complete" | "aborted" | "error";

/** One model step of a turn: a tool-calling step or the final answer step. */
export interface TurnStep {
  startedAt: number;
  /** When the step's first text arrived. The final answer's step is the last one with text. */
  firstTextAt?: number;
  endedAt?: number;
  finishReason?: string;
}

export interface TurnTiming {
  startedAt: number;
  endedAt?: number;
  steps: TurnStep[];
  /**
   * One entry per reasoning block of the turn, in stream order. The n-th reasoning part of the message is the
   * n-th entry here. Epoch milliseconds.
   */
  reasonings?: { startedAt: number; endedAt?: number }[];
}

export interface StoredMessageMetadata {
  /** Facts recalled from Hindsight that were injected into this user message for the model. */
  memory?: {
    query: string;
    budget: string;
    facts: { id: string; text: string; type?: string }[];
  };
  model?: string;
  /** The assistant turn's timing, measured by the server. Epoch milliseconds. */
  turnTiming?: TurnTiming;
  /** assistant-ui's composer quote, kept under the same key the runtime uses (metadata.custom). */
  custom?: { quote?: { text: string; messageId?: string } };
}

export const messages = pgTable(
  "messages",
  {
    id: text("id").primaryKey(),
    conversationId: uuid("conversation_id")
      .notNull()
      .references(() => conversations.id, { onDelete: "cascade" }),
    role: text("role").$type<"user" | "assistant" | "system">().notNull(),
    position: integer("position").notNull(),
    parts: jsonb("parts").$type<UIMessage["parts"]>().notNull(),
    metadata: jsonb("metadata").$type<StoredMessageMetadata>(),
    status: text("status").$type<MessageStatus>().notNull().default("complete"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [index("messages_conversation_position_idx").on(table.conversationId, table.position)],
);
